// Do not edit this file as it will be overwritten if HAMR codegen is rerun

use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_control_basis: Isolette_Thermostat_Rust::MonitorControlBasis,
  pub api_monitor_mode: Isolette_Thermostat_Rust::ThermostatMode
}

/// container for component's incoming port values and GUMBO state variables
pub struct PreStateContainer_wGSV {
  pub In_alarm_control_state: Isolette_Thermostat_Rust::AlarmCommand,
  pub api_control_basis: Isolette_Thermostat_Rust::MonitorControlBasis,
  pub api_monitor_mode: Isolette_Thermostat_Rust::ThermostatMode
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_control_basis(container.api_control_basis);
  put_monitor_mode(container.api_monitor_mode);
}

/// setter for component's incoming port values and GUMBO state variables
pub fn put_concrete_inputs_container_wGSV(container: PreStateContainer_wGSV)
{
  put_alarm_control_state(container.In_alarm_control_state);
  put_control_basis(container.api_control_basis);
  put_monitor_mode(container.api_monitor_mode);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(
  control_basis: Isolette_Thermostat_Rust::MonitorControlBasis,
  monitor_mode: Isolette_Thermostat_Rust::ThermostatMode)
{
  put_control_basis(control_basis);
  put_monitor_mode(monitor_mode);
}

/// setter for component's incoming port values and GUMBO state variables
pub fn put_concrete_inputs_wGSV(
  In_alarm_control_state: Isolette_Thermostat_Rust::AlarmCommand,
  control_basis: Isolette_Thermostat_Rust::MonitorControlBasis,
  monitor_mode: Isolette_Thermostat_Rust::ThermostatMode)
{
  put_alarm_control_state(In_alarm_control_state);
  put_control_basis(control_basis);
  put_monitor_mode(monitor_mode);
}

/// setter for IN DataPort
pub fn put_control_basis(value: Isolette_Thermostat_Rust::MonitorControlBasis)
{
  *extern_api::IN_control_basis.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_monitor_mode(value: Isolette_Thermostat_Rust::ThermostatMode)
{
  *extern_api::IN_monitor_mode.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_alarm_control() -> Isolette_Thermostat_Rust::AlarmCommand
{
  return extern_api::OUT_alarm_control.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}

/// getter for GUMBO State Variable
pub fn get_alarm_control_state() -> Isolette_Thermostat_Rust::AlarmCommand
{
  unsafe {
    match &crate::app {
      Some(inner) => inner.alarm_control_state,
      None => panic!("The app is None")
    }
  }
}

/// setter for GUMBO State Variable
pub fn put_alarm_control_state(value: Isolette_Thermostat_Rust::AlarmCommand)
{
  unsafe {
    match &mut crate::app {
      Some(inner) => inner.alarm_control_state = value,
      None => panic!("The app is None")
    }
  }
}
